import { action, observable, makeObservable } from "mobx";
import PageStore from '../store';

class Store {
    @observable text: string = "";

    @action setText = (text) => {
        this.text = text;
    }


    pageStore:PageStore;

    constructor(store) {
        this.pageStore = store;
        makeObservable(this);
    }
}



export default Store;