import React, {
  useEffect,
  useRef,
  useState,
  useCallback,
  useMemo,
  HTMLProps,
} from 'react';
import styles from './index.module.less';
import { Tooltip } from '@arco-design/web-react';
import Store from '../store';
import Control from '../components/Control';
import { ButtonItem } from '../interface';

const scaleX = new Array(30).fill(0).map((_, i) => i * 100 - 1000);
const scaleY = new Array(50).fill(0).map((_, i) => i * 100 - 500);

{
  /* 横向坐标尺 */
}
interface RulerXProps {
  // top: number;
}
const RulerX = ({}: RulerXProps) => {
  return (
    <div className={styles.rulerX} style={{ width: scaleX.length * 100 }}>
      {scaleX.map((num: number) => (
        <span key={num}>{num}</span>
      ))}
    </div>
  );
};

{
  /* 竖向坐标 */
}
interface RulerYProps {
  // left: number;
}
const RulerY = ({}: RulerYProps) => {
  return (
    <div className={styles.rulerY} style={{ height: scaleY.length * 100 }}>
      {scaleY.map((num: number) => (
        <span key={num}>{num}</span>
      ))}
    </div>
  );
};

interface CanvasProps extends HTMLProps<HTMLDivElement> {
  // 缩放比例
  scale?: number;
  // 是否可以拖动组件
  isDidDrop?: boolean;
  children?: any;
  controlList?: ButtonItem[];
  store: Store;
}
const Index = ({ children, isDidDrop, scale, store, controlList, ...props }: CanvasProps) => {
  const canvasRef = useRef(null);
  // const [top, setTop] = useState(430);
  // const [left, setLeft] = useState(930);

  const resetScroll = useCallback((top, left) => {
    const demo: any = canvasRef.current;
    demo.scrollTop = top;
    demo.scrollLeft = left;
  }, []);

  const scalePct = useMemo(() => {
    return 100 - 10000 / scale;
  }, [scale]);

  useEffect(() => {
    const demo: any = canvasRef.current;
    resetScroll(430, 930);
    // function onScroll(e:any){
    //   if(isDidDrop){
    //     demo.scrollTop = top;
    //     demo.scrollLeft = left;
    //   }
    //   const { scrollTop, scrollLeft } = demo;
    //   setTop(scrollTop);
    //   setLeft(scrollLeft)
    // }
    // demo.addEventListener('scroll',onScroll);

    // return () => {
    //   demo.removeEventListener('scroll',onScroll);
    // }
  }, [isDidDrop]);

  return (
    <div style={{ position: 'relative', flex: 1, height: '100%' }}
      { ...props }
    >
      <div
        className={styles.canvas}
        onClick={() => {}}
        style={{
          transform: `scale(${scale / 100})`,
          right: `${scalePct}%`,
          bottom: `${scalePct}%`,
        }}
        ref={canvasRef}
      >
        <RulerX />
        <RulerY />
        {children}
      </div>
      <Tooltip content="回到开始位置">
        <div
          className={styles.canvasScaleMake}
          onClick={() => resetScroll(430, 930)}
        ></div>
      </Tooltip>
      {store.control && (
        <Control store={store} controlList={controlList} />
      )}
    </div>
  );
};

export default Index;
