import { MobileKey } from "@/types/mobile";
import React, { useEffect, useMemo, useRef, useState } from "react";
import Store from './store';
import { useObserver } from "mobx-react-lite";
import { Spin } from "@arco-design/web-react";
import { moduleStore } from "react-converter-code";
import fileStore from "@/store/file";
import app from "@/store/app";
import language from '@/store/language'
import { IfrmaePageDataProps } from "./interface";
import styles from './style.module.less';
import _ from "lodash";

export const MobileStore = Store;

interface MobileViewProps {
    store: Store;
    isMobile: boolean;
}
const Index = ({ store, isMobile }: MobileViewProps) => {

    const iframeRef = useRef<any>();

    const [loading, setLoading] = useState(false);

    const modulePropos = useMemo(() => {
        const element = moduleStore.elements.get(store.pageStore.uid);
        if(!element) return {};
        return element.extraInfo.initialProps;
    },[])

    const sendMessageToIframe = () => {
        const iframe = iframeRef.current;
        if (iframe) {
            iframe.contentWindow.postMessage({
                key: MobileKey.TemplateProps,
                data: JSON.stringify(modulePropos)
            })
            iframe.contentWindow.postMessage({
                key: MobileKey.Template,
                data: store.text
            });
        }
    };

    const onLoadHtml = () => {
        const iframe = iframeRef.current;
        var iframeDoc = iframe.contentDocument || iframe.contentWindow.document;
        
        iframeDoc.open();  // 清空文档并开始写入
        iframeDoc.write(`
            <html>
                <head>
                    <link href="https://wizui-assets.oss-cn-hangzhou.aliyuncs.com/umd/@arco-design/web-react@2.63.1/dist/css/arco.min.css"  rel="stylesheet" />
                    <script src="https://wizui-assets.oss-cn-hangzhou.aliyuncs.com/umd/tailwindcss/3.4.3/tailwindcss.js"></script>
                </head>
                <body>
                    <div id="app">Loading...</div>
                    <script id="delete-script">
                        console.log('parentData', window.parentData);
                        window.parentData.onIframeLoad(window)
                        setTimeout(() => {
                            document.getElementById('delete-script').remove();
                        },300)
                    </script>
                </body>
            </html>    
        `);
        iframeDoc.close();  // 完成文档写入并渲染
    }

    
    return useObserver(() => {

        useEffect(() => {
            sendMessageToIframe();
        },[store.text])

        useEffect(() => {

            const handleMessage = (event) => {
                console.log('父窗口收到消息:', event.data);
                if(typeof event.data == "object"){
                    const { key } = event.data;
                    switch(key){
                        case MobileKey.ready:
                            // 发送配置信息
                            sendMessageToIframe();
                        break;
                    }
                }
            };
        
            window.addEventListener('message', handleMessage);
        
            return () => {
              window.removeEventListener('message', handleMessage);
            };
        }, []);

        useEffect(() => {
            const iframe = iframeRef.current;
            console.log('iframe', iframe)
            if(iframe){
                iframe.contentWindow.React = window.React
                Object.assign(
                    iframe.contentWindow,
                    {
                        iframePage: true,
                        moduleStore: moduleStore,
                        fileStore: fileStore,
                        app: app,
                        language: language,
                    } as IfrmaePageDataProps
                )
            }
        },[])
    
        return (
            <Spin
                loading={loading}
                block
                className={
                    `${styles.spin} h-full mx-auto border-dashed border-gray-400 bg-white block ${isMobile? 'w-96' : 'w-full'}`
                }
            >
                <iframe
                    ref={iframeRef}
                    // src={`${location.origin}/#/mobile/view`}
                    // src={`${location.origin}/iframe.html`}
                    src="/"
                    title="H5 Page"
                    className="w-full h-full"
                    onLoad={(e) => {
                        setLoading(false)
                        // onLoadHtml();
                    }}
                >
                </iframe>
            </Spin>
        )
    })
}


export default Index;