import { ContextProps } from "@/components/CustomPage/context";
import CustomPageStore from "@/components/CustomPage/store";
import { SelectProps } from "@arco-design/web-react";
import { toJS } from "mobx";
import business from "@/store/business";
import { moduleStore } from "react-converter-code";

class Store {
    
    store: CustomPageStore;
    dialogOptions: SelectProps['options'] = [];
    formOptions: SelectProps['options'] = [];
    tableOptions: SelectProps['options'] = [];
    busOptionNode: Record<string, SelectProps['options']> = {};

    constructor(data: ContextProps){
        if(data){
            this.store = data.pageStore;
            const pageData = toJS(this.store.getData());
            const { list, components } = pageData;
            for (const item of list) {
                const { name, props = {} } = item;
                switch(name){
                    case "GPageForm":
                        if(props.modelKey){
                            this.formOptions.push({ value: props.modelKey, label: props.modelKey });
                        }
                        const info = business.info[props.tableId];
                        if(info){
                            this.busOptionNode = {
                                [props.modelKey]: info.tables.map((o) => ({
                                    label: o.tableName,
                                    value: o.itemTableName,
                                }))
                            }
                        }
                    break;
                    case "GDialog":
                    case "CDialogUser":
                        if(props.mark){
                            this.dialogOptions.push({ value: props.mark, label: props.mark });
                        }
                    break;
                    case "CTable":
                    case "GTable":
                        if(props.tableKey){
                            this.tableOptions.push({ value: props.tableKey, label: props.tableKey })
                        }
                    break;
                }
            }
            console.log('this', this)
        }
    }

}

export default Store;