import ajax from "@/utils/ajax";
import { htmlModuleList } from "@/utils/database";
import PageStore from '../store';
import app from '@/store/app';
import { action, observable, makeObservable } from "mobx";
import { moduleSource, moduleTypes } from "@/types/module";
import { getModuleItem } from "@/utils/module";
import { ModuleItem } from "@/components/CustomPage/interface";
import { basicsModuleList } from "react-converter-code";
import module from "@/store/module";
import { moduleList } from "@/environments/module";

interface componentItem {
  key: string,
  name: string,
  modules: ModuleItem[];
}
class Store {

    htmls = htmlModuleList;

    @observable loading = false;
    @action
    setLoading = (bool) => {
      this.loading = bool;
    };

    getItem = getModuleItem;

    // 内置组件库
    @observable components: componentItem[] = [];
    @action
    setComponents = (list) => {
      this.components = list;
    }

    constructor(){
      makeObservable(this);
      // 加载所有内置组件
      const keys = ['basics', ...Object.keys(moduleTypes)];
      let map = new Map(keys.map((k) => [k, { key: k, name: moduleTypes[k], modules: [] }]))
      // console.log('modules', map)
      map.set("basics", {
        key: "basics",
        name: "基础",
        modules: basicsModuleList
      })
      map.set("context", {
        key: "context",
        name: "Context",
        modules: [],
      })
      const list: any[] = moduleList.map((o) => {
        return {
          ...o,
          extraInfo: {}
        }
      });
      // console.log('list', list, map);
      for (const item of list) {
        const mapItem = map.get(item.category);
        mapItem.modules.push(item);
        map.set(item.category, mapItem);
      }
      this.setComponents(Array.from(map.values()).filter((o) => o.modules.length));
    }

    // 自定义组件
    @observable customs: componentItem[] = [];
    @action
    setCustom = (list) => {
      this.customs = list;
    }

    isReady = false;

    getComponents = (pageStore: PageStore) => {
        this.setLoading(true);
        // 获取组件列表
        return ajax.post('/apijson/get', {
          'Module[]': {
            count: 0,
            Module: {
              "moduleId{}": pageStore.moduleFilterIds,
              platform: pageStore.platform,
              deletedTime: 0,
              "@column": "id,moduleId,name,imgUrl,nickname,description,deletedTime,category,display,extraInfo,platform,price,manufacturer,props,source",
              "@order": "createdAt+"
            }
          }
        }, {}).then((res) => {
          module.setModulesList(res.Module.map((o) => ({ key: o.moduleId, ...o })));
          const keys = [...Object.keys(moduleTypes)];
          let cMap = new Map(keys.map((k) => [k, { key: k, name: moduleTypes[k], modules: [] }]));
          if(Array.isArray(res.Module)){
            const contextList = [];
            for (const item of res.Module) {
              if(item.category){
                if(item.source === moduleSource.context) {
                  contextList.push(this.getItem(item));
                }else {
                  const cMapItem = cMap.get(item.category);
                  cMapItem.modules.push(this.getItem(item));
                  cMap.set(item.category, cMapItem);
                }
              }
            }
            cMap.set("context", {
              key: "context",
              name: "Context",
              modules: contextList,
            })
            this.setCustom(Array.from(cMap.values()).filter((o) => o.modules.length));
          }
        }).finally(() => {
          this.setLoading(false)
        })
    }


    
}

export default new Store();