import store from '@/store';
import { getUuid } from '@/utils';
import { Message, Upload, UploadProps } from '@arco-design/web-react';
import { useObserver } from 'mobx-react-lite';
import { useEffect, useMemo, useState } from 'react';
import config from 'mainConfig';
import Store from './store';

/**
 * 方便用户图片上传，主要改动点
 * @tip1 自定义 value 接管了 list ( 为了 form 表单接管状态方便 )
 * @tip2 默认value 是string 类型，如果想要上传多个图片 可以使用 multipleChoice
 */
export interface UploaderProps extends Omit<UploadProps, 'onChange'> {
  value?: string | string[];
  store?: Store;
  // 是否开启多选
  multipleChoice?: boolean;
  onChange?: (value: string | string[], list: any | any[]) => void;
}

const Uploader = ({ value, onChange, multipleChoice, store:uStore, ...props }: UploaderProps) => {

  const [store] = useState(() => uStore || new Store())
  return useObserver(() => {

    const values = useMemo(() => {
      if(!value) return [];
      const values = Array.isArray(value)? value : [value];
      return values;
    },[value])

    useEffect(() => {
      if(!values.length) {
        store.setList([]);
      };
      const map = new Map(store.list.filter((o) => o.url).map((o) => [o.url, o]));
      const list = values.filter((url) => !map.has(url));
      if(list.length){
        store.setList(store.list.concat(list.map((url) => {
          return {
            uid: getUuid(),
            url: url,
            status: 'done'
          }
        })))
      }
    },[values])


    return (
        <Upload
          imagePreview
          name="file"
          limit={multipleChoice? 9 : 1}
          // headers = {{
          //   "Content-Type": "multipart/form-data;"
          // }}
          action={`${import.meta.env.VITE_API_BASE_PATH}/codes/upload`}
          headers={{
            Authorization: `Bearer ${localStorage.getItem(config.TokenKey)}`
          }}
          listType='picture-card'
          accept='image/*'
          {...props}
          fileList={store.list}
          onChange={(list) => {
            // console.log('setList', JSON.parse(JSON.stringify(list[0])))
            store.setList(list)
            if(onChange && JSON.stringify(store.value) !== JSON.stringify(values)){
              // 文件列表变更
              if(multipleChoice){
                // 多选
                onChange(store.value, store.list);
              }else {
                onChange(store.value[0], store.list[0]);
              }
            }
          }}
        />
    );
  })
};
  
export default Uploader;