import { buildColumnItem, MethodItem, VarItem } from '@/types/expression';
import { JSONSchemaItemProps } from '@/types/schema';
import { getFieldSchema, getUuid } from '@/utils';
import { get as safeGet } from 'lodash'
import { action, computed, observable, toJS, makeObservable } from 'mobx';
import ReactDOM from 'react-dom';
import Index from './index';
import _ from 'lodash';



const methods: Record<string, MethodItem[]> = {
	array: [
		{
			id: '1',
			name: 'length',
		}
	],
	string: [
		{
			id: '2',
			name: 'length',
		},
		{
			id: '3',
			name: 'toLocaleLowerCase',
		},
		{
			id: '4',
			name: 'toLocaleUpperCase',
		}
	]
}

interface selectedItem {
	type: 'var' | 'method',
	id: string;
	// 当前字段名称
	name: string;
}

class Store {

    // 已选择数据列表
    @observable buildList: buildColumnItem[] = [];

    getDefault = () => {
        // schemaToList()
    }

    constructor(){
        makeObservable(this);
    }

	// 创建一个 React 弹窗组件
	dom = document.createElement('div');
	createReactDOM = () => {
		ReactDOM.render(
			<Index store={this} />,
			this.dom
		)
		// document.body.appendChild(this.dom);
	}
	// 卸载弹窗组件
	removeReactDOM = () => {
		ReactDOM.unmountComponentAtNode(this.dom);
		// this.dom.parentNode.removeChild(this.dom);
	}

	@observable visible = false;
	// 打开弹窗
	@action
	openDialog = () => {
		this.visible = true;
		this.createReactDOM();

	}
	@action
	closeDialog = () => {
		this.visible = false;
		this.removeReactDOM();
		this.promise = null;
	}



	// 数据源
	dataSource = {}
	// 数据源对应的schema 文档
	dataSchema: JSONSchema = {
		"type": "object",
		"properties": {
		}
	}

	promise = null;

    /**
     * 初始化方法
     */
	@action
    init = (source: any = {}, schema: JSONSchema = { type: "object", properties: {} }) => {
		this.dataSource = source;
		this.dataSchema = schema;
        // 初始化方法执行
        const item = this.getBuildList(this.dataSource, []);
		if(item){
			this.buildList = [item];
		}
		return new Promise((resolve, reject) => {
			this.promise = { resolve, reject }
			this.openDialog();
		})
    }


	/**
	 * 根据数据，返回BuildList 信息
	 */
	@action
	getBuildList = (val: any, paths: string[]): buildColumnItem => {

		switch(typeof val){
			case 'string':
				return {
					id: getUuid(),
					varsList: [{
						id: getUuid(),
						field: 'length'
					}],
				}
			case 'object':
				if(val){
					const keys = Object.keys(val);

					const item: buildColumnItem = {
						id: getUuid(),
						varsList: [],
						methodList: [],
					}
					for (const key of keys) {
						const schema = getFieldSchema(this.dataSchema, [...paths, key]);
						item.varsList.push({
							id: getUuid(),
							field: key,
							schema,
						})
						if(val[key] && typeof val[key] === "function"){
							item.methodList.push({
								schema,
								id: getUuid(),
								name: `${key}()`,
							})
						}
					}
					if(Array.isArray(val)){
						item.varsList.unshift({ id: getUuid(), field: 'length' })
					}
					return item;
				}
		}

		return {
			id: getUuid(),
			varsList: []
		}
	}

	/**
	 * 根据 type 类型
	 * 获取事件列表
	 */
	getMethods = (val: any): MethodItem[] =>{ 

		switch(typeof val){
			case 'object':
				if(Array.isArray(val)){
					// array
					return methods['array'];
				}
			case 'boolean':
				return []
			case 'number':
			case 'string':
				return methods['string'];
		}

		return [];
	}


	// 当前用户选择的数据内容
	@observable selecteds: selectedItem[] = [];

	// 返回当前选择路径
	getSelectedPaths = (list: selectedItem[]): string[] => {
		return list.map((o) => o.name);
	}

	// 根据选择内容返回数据列表
	@computed get expressionText(){
		const paths = this.getSelectedPaths(this.selecteds);
		return '${ ' + `${paths.map((s) => `\`${s}\``).join('.')}` + ' }';
	}

	@computed get data(){
		const paths = this.getSelectedPaths(this.selecteds);
		const value = _.get(this.dataSource, paths)

		// console.log('obj', this.dataSource, value)
		return value;
	}

	@computed get dataText(){
		if(typeof this.data === 'object'){
			return JSON.stringify(this.data, null, '\t');
		}
		// console.log('data', this.data);

		return String(this.data);
	}
	/**
	 * 新增选中的对象
	 */
	@action addSelectedVars= ($index: number, item: VarItem) => {
		const selecteds = this.selecteds;
		selecteds.splice($index);
		const buildList = this.buildList;
		buildList.splice($index + 1);
		
		selecteds.push({
			type: 'var',
			id: item.id,
			name: `${item.field}`
		})

		const paths = this.getSelectedPaths(selecteds);
		const value = safeGet(this.dataSource, paths);

		const buildItem = this.getBuildList(value, paths);
		if(buildItem){
			buildList.push(buildItem);
		}
		
		this.selecteds = [...selecteds];
		this.buildList = buildList;

		// console.log('buildList', toJS(buildList), toJS(selecteds))
	}

	/**
	 * 新增选择的方法
	 */
	 @action addSelectedMethod= ($index: number, item: MethodItem) => {
		const selecteds = this.selecteds;
		selecteds.splice($index);
		const buildList = this.buildList;
		buildList.splice($index + 1);
		
		selecteds.push({
			type: 'var',
			id: item.id,
			name: item.name
		})

		const varsList = [];
		// const methodList = this.getMethods(item.type);
		// if(varsList.length && methodList.length){
		// 	buildList.push({
		// 		id: getUuid(),
		// 		varsList,
		// 		methodList,
		// 	})
		// }
		
		this.selecteds = [...selecteds];
		this.buildList = buildList;

		// console.log('buildList', toJS(buildList), toJS(selecteds))
	}


	onOk = () => {
		if(this.promise){
			if(this.selecteds.length){
				this.promise.resolve({ value: this.expressionText });
			}else {
				this.promise.reject();
			}
		}
		this.closeDialog();
	}
    
}

export default Store;