import React, { useState } from 'react';
import styles from './index.module.less';
import { MonacoLessEditor } from '@/components/MonacoEditor';
import { Modal, ModalProps } from '@arco-design/web-react';

interface PageCssProps extends ModalProps {
    lessStr: string;
    onSuccess: (lessStr: string) => void;
}
const PageCss = ({ lessStr, onSuccess, ...props}: PageCssProps) => {

    const [value, setValue] = useState<string>(lessStr);

    console.log('PageCss', lessStr, value)
    return (
        <div onClick={(e) => e.stopPropagation()}>
            <Modal
                title="样式文件（Less）"
                style={{ width: 800 }}
                visible
                onOk={async () => {
                    if(onSuccess){
                        onSuccess(value);
                    }
                }}
                {...props}
            > 
                <MonacoLessEditor value={value} onChange={setValue} />
            </Modal>
        </div>
    )

}

export default PageCss;