export default `
import _ from 'lodash';
import ajax from './ajax';
import { history } from './history';
import classNames from 'classnames';


// 判断是否为函数类型
function isFunction(val): boolean {
    return typeof val === 'function';
}

// 判断是否为promise 类型
function isPromise(val): boolean {
    return typeof val === 'object' && isFunction(val.then) && isFunction(val.catch) && isFunction(val.finally);
}

// 随机生成uuid
const getUuid = (type?: "hash") => {
    function S4() {
      return (((1 + Math.random()) * 0x10000) | 0).toString(16).substring(1);
    }
    if(type === "hash"){
      return \`\${S4()}\${S4()}\`;
    }else if(crypto && crypto.randomUUID) {
      return  crypto.randomUUID()
    }
    return S4() + S4() + '-' + S4() + '-' + S4() + '-' + S4() + '-' + S4() + S4() + S4();
};



export default {
    ajax,
    classNames,
    isFunction,
    isPromise,
    getUuid,
    history,
}

`