/**
 * 获取引用文件名称
 * @param present 当前路径（目录） /react/
 * @param path 索引到的路径 ./types.ts
 * @returns { fileName: string, filePath: string }
 */
export function getImportFilePath(present: string, path: string): {
    fileName: string;
    filePath: string;
  }{
      let filePath = path;
      let defaultName = 'index.d.ts';
      let paths = present.split('/').filter((o) => o);
      if(path.slice(0,3) === '../'){
        paths.pop();
        filePath = path.slice(3);
      }else if(path.slice(0,2) === './') {
        filePath = path.slice(2);
      }else {
        paths = [];
        defaultName = 'package.json'
      }
      paths.push(filePath);
      paths = paths.join('/').split('/');
      let fileName = paths.pop();
      // if(fileName.indexOf('.') === -1){
      //   // 逻辑在外层进行处理
      //   if(fileName === 'interface'){
      //     fileName = `${fileName}.d.ts`;
      //   }else {
      //     fileName = `${fileName}/${defaultName}`;
      //   }
      // }
      return {
        fileName,
        filePath: paths.join('/')
      }
  }
  
  /**
   * @title 解析文本中所有引入到imports 路径
   */
  export function parseImportPaths(tsFileContent): string[] {
    
      // 正则表达式用于匹配import语句中的路径
      const importRegex = /from\s+["']([^"']+)["']/g;
    
      const importPaths = [];
    
      let match;
      while ((match = importRegex.exec(tsFileContent))) {
        importPaths.push(match[1]);
      }
    
      return importPaths;
  }



/**
 * 将列表根据路径进行分层
 */
export function processPageList(list: any[], pathKey: string) {
    const contents: any[] = [];

    const loop = (item) => {
      const path = item[pathKey];
      const existingIndex = contents.findIndex((o) => o.id == path);
      // 如果当前路径已经存在，则不进行添加
      if (existingIndex != -1) {
        contents[existingIndex].item = item;
        return
      };
  
      const paths = path.split('/');
      const fileName = paths.pop();
      const length = paths.length;
  
      if(paths.length >= 1){
        for (let i = 0; i < length; i++) {
          const key = paths.slice(0, i + 1).join('/');
          const existingItem = contents.find((o) => o.path === key);
          // 如果当前路径不存在，创建一个
          if (!existingItem && key) {
              contents.push({
                  id: key,
                  path: key,
                  fileName: paths[i],
                  parentPath: i ? paths.slice(0, i).join('/') : ''
              });
          }
        }
      }
  
      contents.push({
          id: path,
          item: item,
          path,
          fileName,
          parentPath: paths.join('/')
      });
   
    }
    for (const item of list) {
      loop(item);
    }
    return contents;
}
