import { delayedFunction } from "@/utils";
import * as monaco from 'monaco-editor';
import config from 'mainConfig';
import ajax from "@/utils/ajax";
import { action, observable, toJS, makeObservable } from "mobx";
import { ContentItem, fileItem } from "./interface";
import { getImportFilePath, parseImportPaths } from "@/utils/path";
import { fileDatas } from './data';
import FileStore from "./Contents/fileStore";
import app from "@/store/app";
import { parseZipFile } from "@/utils/zip";
import { EditReactNode } from "@/components/custom";
import React, { ReactNode } from "react";
import { generateReadableJson } from "@/utils/json";
import language from "@/store/language";
import appFile from "@/store/file";

const languages = {
    'ts': "typescript",
    'js': "javascript",
    "tsx": "typescript",
}
const urlHash = {};
const node_modules: any = [];
export class Store {
    // modal 模型
    model: monaco.editor.ITextModel;
    // 当前打开的文件
    @observable uri: monaco.Uri;
    /**
     * 记录当前文件滚动位置信息
     */
    urlScrollMap = {};
    // 更新当前打开的文件
    @action
    setUri(uri) {
        this.uri = uri;
    }
    // 创建monaco editor 编译器
    monacoInstance: any;
    // 记录最近编辑器的光标位置
    position: any;

    data: string = "";
    setData = (data) => {
        this.data = data
        const fileStore = this.fileStores[this.uri.path];
        if (fileStore) {
            fileStore.setDataStr(data);
        }
        this.setPostions();
    };

    // 修改内容时记录当前光标位置
    setPostions = delayedFunction(() => {
        if (this.monacoInstance) {
            this.position = this.monacoInstance.getPosition();
        }
    }, 300);

    constructor() {
        makeObservable(this);
        if (node_modules.length === 0) {
            for (const data of fileDatas) {
                // 初始化时添加新的数据
                this.addNodeModules(data.path, data.data, '');
            }
            // 写入多语言信息
            this.initLanguages();
            // 写入静态资源文件
            this.initStatic();
            // 写入config 配置
            this.addNodeModules('config.ts', `export default ${ generateReadableJson(app.allVariablesSchema, app.extraInfo.configuration) }`)
        }
    }

    /**
     * 写入多语言信息
     */
    initLanguages(){
        for (const item of language.AppOptions) {
            this.addNodeModules(
                `locales/lang/${item.value.replace('-', '')}.ts`,
                `export default ${JSON.stringify(item.data, null, '\t')}`,
                ''
            )
        }
    }

    /**
     * 写入文件信息
     */
    initStatic = async () => {
        for (const item of appFile.list) {
            this.addNodeModules(
                `public/static/${item.fileName}`,
                '',
                //  appFile.downFile(item.filePath),
                ''
            )
        }
    }

    /**
     * 重置文件信息
     */
    @action
    resetStatic = () => {
        for (const item of this.nodeModules) {
            if(item.uri.path.startsWith('/public')){
                item.model.dispose();   // 清理当前模型
            }
        }
        this.nodeModules = this.nodeModules.filter((o) => !o.uri.path.startsWith('/public'));
        this.contents = this.contents.filter((o) => !o.path.startsWith('/public'));
        appFile.getList().then(() => {
            // 重新写入文件
            this.initStatic();
        })
    }

    /**
     * monaco编辑器插入
     */
    insertText(text: string) {
        if (!this.monacoInstance) return false;
        const position = this.position;
        if (position) {
            // 插入数据
            this.monacoInstance.executeEdits("insertData", [{
                range: new monaco.Range(position.lineNumber, position.column, position.lineNumber, position.column),
                text,
            }]);
            // 获取当前插入点的索引
            var index = this.monacoInstance.getModel().getOffsetAt(position);
            // 移动光标到插入数据之后
            this.monacoInstance.setPosition(this.monacoInstance.getModel().getPositionAt(index + text.length));
        } else {
            // 没有坐标直接最后插入
            const value = this.monacoInstance.getValue();
            this.monacoInstance.setValue(`${value}${text}`);
        }
    }

    /**
     * 创建目录
     */
    @observable contents: ContentItem[] = [];
    // 添加目录名称映射
    contentAlias = {};
    fileStores: Record<string, FileStore> = {};
    /**
     * 添加文件/或目录
     */
    @action
    addContents = (uri: monaco.Uri) => {
        const { path } = uri;
        // 当前路径已经存在，不在进行添加
        if (this.contents.find((o) => o.path === path)) return;
        const paths = path.split('/');
        // console.log('paths', paths)
        const fileName = paths.pop();
        const length = paths.length;
        for (let i = 0; i < length; i++) {
            const key = paths.slice(0, i + 1).join('/');
            const item = this.contents.find((O) => O.path == key);
            // 当前路径不存在， 创建一个
            if (!item && key) {
                this.contents.push({
                    path: key,
                    fileName: this.contentAlias[paths[i]] || paths[i],
                    parentPath: i ?
                        paths.slice(0, i).join('/') : ''
                })
            }
        }
        this.contents.push({
            uri,
            fileName: fileName,
            path,
            parentPath: paths.join('/'),
        })
        this.contents = [...this.contents];
    }


    files: fileItem[] = [];
    addFile = (data: string, path): fileItem => {
        const url = monaco.Uri.parse(path)
        const exts = path.split('.');
        const ext = exts.pop();
        const item = {
            data: data,
            language: languages[ext] || ext,
            uri: url,
            model: null,
        }
        this.files.push(item);
        this.createModel(item);
        this.addContents(item.uri);
        this.fileStores[url.path] = new FileStore({ originStr: data })
        return item;
    }


    
    /**
     * 打开文件
     */
    openFile = (uri: monaco.Uri) => {
        this.setUri(uri); // 记录url
        if (!this.monacoInstance || (this.model && this.model.uri.path === uri.path)) {
            // 编辑器未打开，或打开文件和现有文件一致
            return;
        }
        const model = monaco.editor.getModel(uri);
        if (this.monacoInstance) {
            if(this.uri){
                // 记录位置
                this.urlScrollMap[this.uri.fsPath] = {
                    top: this.monacoInstance.getScrollTop(),
                }
            }
            this.monacoInstance.setModel(model)
            this.model = model;
            // 读取位置(并复原)
            const scroll = this.urlScrollMap[uri.fsPath];
            if(scroll){
                this.monacoInstance.setScrollTop(scroll.top);
            }
        };
    }

    nodeModules: fileItem[] = node_modules;
    // 添加 nodeModules 依赖
    addNodeModules = (path, data, prefix = 'node_modules/') => {
        const uri = `file://root/${prefix}${path.replace(/@/, '')}`;
        const exts = path.split('.');
        const ext = exts.pop();
        const url = monaco.Uri.parse(uri)
        const item = {
            data: data,
            language: languages[ext] || ext,
            uri: url,
            model: null,
        }
        item.model = this.createModel(item);
        this.nodeModules.push(item);
        this.addContents(url);
    }

    // 添加node_modules 依赖项
    createModel({ data, language, uri }: fileItem) {
        // console.log('createModel', uri);
        return monaco.editor.createModel(data, language, uri);
    }


    // async checkURLAvailability(url) {
    //   return fetch(url, { method: 'HEAD' })
    //     .then(function (response) {
    //       return response.status === 200;
    //     })
    //     .catch(function () {
    //       return false;
    //     });
    // }
    /**
     * @name key 文件
     * @path 路径
     */
    async getData(key: string, path = 'package.json') {
        // console.log('getData =--key', key,'path= ==>', path)
        const file = `${key ? `${key}/` : ''}${path}`;
        const paths = file.split('/');
        const fileName = paths.pop();
        const filePath = paths.join('/');
        // 加载react 以来
        const cdnUrl = `${config.CDNURL}/umdjs/node_modules/`;
        const url = `${cdnUrl}${file}`;
        if (urlHash[url]) return;
        urlHash[url] = true;
        // if(!this.checkURLAvailability(url)) return;
        const data = await fetch(url).then((res: any) => {
            if (res.status !== 200) return;
            const content = res.text();
            return content;
        });
        if (!data) return;
        this.addNodeModules(file, data);
        if (path === 'package.json') {
            const json = JSON.parse(data);
            const path = json.types || json.main;
            // 加载入口地址
            await this.getData(key, path.replace('./', '')); // 'index.d.ts'
            const keys = Object.keys(json.dependencies || {});
            if (Array.isArray(keys)) {
                await Promise.all(
                    keys.map((key) => this.npmInstall(key))
                )
            }
        } else {
            // 获取所有 form 引入依赖项目
            const list = parseImportPaths(data);
            for (const name of list) {
                const o = getImportFilePath(filePath, name);
                if (o.fileName.indexOf('.') === -1) {
                    // 文件是否存在后缀
                    if (o.fileName[0] === o.fileName[0].toLocaleUpperCase()) {
                        // 大写默认为目录，加载 /index.d.ts 文件
                        o.fileName = `${o.fileName}/index.d.ts`;
                        await this.getData(o.filePath, o.fileName);
                    } else {
                        // 小些，分为多种情况
                        o.fileName = `${o.fileName}.d.ts`
                        await this.getData(o.filePath, o.fileName);
                    }

                } else {
                    await this.getData(o.filePath, o.fileName);
                }
            }
        }
        // console.log('content', key, data);
    }

    // 安装依赖
    async npmInstall(key = '@types/react') {
        if (urlHash[key]) return;
        urlHash[key] = true;
        if (key === '@types/scheduler') {
            this.getData(key, 'tracing.d.ts')
        }
        const text = await this.getData(key);
        // console.log('npmInstall', text);
    }

    // 从zip安装依赖
    async npmInstallZip(key: string) {
        if (urlHash[key]) return;
        urlHash[key] = true;
        const zipUrl = `${config.CDNURL}/${key}.zip?t=10112311221`;
        const list = await parseZipFile(zipUrl);
        console.log('npmInstallZip', list);
        for (const item of list) {
            const file = `${item.url.replace(`${key}/`, '')}`;
            if (
                item.text && 
                (
                    file.endsWith('.tsx') 
                    || file.endsWith('.ts')
                    || file.endsWith('.d.ts')
                    || file.endsWith('interface.ts')
                    || file.endsWith('interface.d.ts')
                )
            ) this.addNodeModules(file, item.text)
        }
    }


}

export default Store;
