import React from "react";
import ajax from "@/utils/ajax";
import { action, computed, observable, makeObservable } from "mobx";

class Store {
    isReady = false;

    @observable loading = false;
    @action setLoading = (bool) => {
        this.loading = bool
    }

    tags: any[] = [];
    @observable imageList: any[] = [];
    @action setImageList = (data) => {
        this.imageList = data;
    }

    @observable tagId = "";
    @observable setTagId = (id) => {
        this.tagId = id;
    }


    constructor() {
        makeObservable(this);
    }


    @computed get list(){
        if(this.tagId) return this.imageList.filter((o) => o.tagId == this.tagId);
        return this.imageList;
    }

    init = async () => {
        if(this.isReady) return null;
        await this.getTags();
        await this.getImageList();
    }

    getTags = () => {
        const params: any = { };

        return ajax.post('/apijson/get', {
            "ImageTag[]": {
                count: 0,
                "ImageTag": {
                    "isActive": 1,
                    "@column": "id,name",
                }
            }
        }).then((res) => {
            this.tags = res.ImageTag;
        })
    }

    getImageList = () => {
        const params: any = {};
        params['tagId{}'] = this.tags.map((o) => o.id)

        ajax.post('/apijson/get', {
            "ImageList[]": {
                "count": 999,
                "ImageList": {
                    ...params,
                    "@column": "id,tagId,name,url",
                }
            }
        }).then((res) => {
            this.setImageList(res.ImageList);
            this.isReady = true;
        })
    }
}

export default new Store();