import ajax from "@/utils/ajax";
import { ReactNode } from "react";
import { convertToTree } from '@/utils'
import app from "@/store/app";
// import { getSelectorItems } from "@/api";
import { ParamsProps, TreeDatasProps } from "./interface";
import utils from "@/environments/utils";
import { processPageList } from "@/utils/path";


const getArctype = (type: number) => {
  return {
    find: ({ params = {} }: ParamsProps) => {
      return ajax.post('/apijson/get', {
          "Arctype[]":{
            "count": 0,
            "Arctype":{
              ...params,
              "ishidden": 1,
              "channeltype": type,
              "@order":"sortrank+",
              "@column":"id,typename,sortrank,reid"
            }
          },
        }).then((res) => {
          return convertToTree(res.Arctype, "id", "reid");
        })
    },
    fieldNames: {
      key: 'id',
      title: 'typename',
    }
  }
}

export default {
  // CONFIGURATION: {
  //   fieldNames: {
  //     key: "type",
  //     title: "name",
  //   },
  //   find: ({}) => {
  //     return getSelectorItems().then((res) => {
  //       return res.filter((o) => o.classify === "tree")
  //     });
  //   }
  // },
  "Arctype1": getArctype(1),
  "Arctype2": getArctype(2),
  "Arctype3": getArctype(3),
  "Arctype7": getArctype(7),
  'menu': {
    find: ({ params = {} }: ParamsProps) => {
      return ajax.post('/apijson/get', {
          "Menu[]":{
            "count": 0,
            "Menu":{
              ...params,
              "type{}": ["directory", "layout"],
              "@order":"sort+",
              "@column":"id,name,sort,parentId"
            }
          },
        }).then((res) => {
          return convertToTree(res.Menu);
        })
    },
    fieldNames: {
      key: 'id',
      title: 'name',
    }
  },
  'api': {
    find: ({ params = {} }: ParamsProps) => {
      return ajax.post('/apijson/get', {
        "ApiInfo[]": {
          "count": 0,
          "ApiInfo": {
            ...params,
            "@order":"sort+",
            "@column":"id,name,type,sort,parentId,data,method,url"
          }
        }
      }).then((res) => {
        const result =  convertToTree(res.ApiInfo.map((o) => {
          if(o.type === "categor"){
            return {
              ...o,
              disabled: true,
            }
          }
          return o;
        }))

        return result;
      })
    }
  },
  "page": {
    find: ({ params = {} }: ParamsProps) => {
      return ajax.post('/apijson/get', {
        "Page[]": {
          "count": 0,
          "Page": {
            "@order":"sort+",
          }
        }
      }).then((res) => {
        return convertToTree(
            processPageList(res.Page, "title").map((o) => {
              return {
                ...o,
                id: o.item? o.item.id : o.id,
                disabled: !Boolean(o.item),
              }
            })
            ,"path", "parentPath"
          );
      })
    },
    fieldNames: {
      key: 'id',
      title: 'fileName',
    }
  }
} as {
    [key in string]: TreeDatasProps
};
