import { MonacoJSEditor, MonacoJsProps } from "@/components/MonacoEditor";
import { Button, Divider, Message, Modal, Space, Typography, Form } from "@arco-design/web-react";
import { IconBranch, IconCodeBlock, IconLink, IconEdit } from "@arco-design/web-react/icon";
import { useEffect, useRef, useState } from "react";
import Hljs from "../Hljs";
import { schemaToJSON } from "@/utils/schema";
import { tsTojsString } from "@/utils/js";


export interface EditFunctionProps extends MonacoJsProps {
    functionType?: JSONSchema['functionType'];
    isFunction?: boolean;
    defaultValue?: string;
    isHljs?: boolean; // 默认展示Button 按钮
}

function EditFunction({ isFunction, isHljs, functionType, ...props }: EditFunctionProps){

    const [visible, setVisible] = useState<boolean>(false);
    const [value, setValue] = useState<any>(() => {
        if (props.value) return props.value;
        if (props.defaultValue) return props.defaultValue;
        if(isFunction){
            if(functionType){
                const { arguments: args, isPromise, return: returnType } = functionType;
                const params = args? args.map((o) => o.title) : [];
                const getReturnStr = () => {
                    if(returnType){
                        const str = JSON.stringify(schemaToJSON(returnType), null, '\t');
                        if(str) return `return ${str}`
                    }
                    return ""
                }
                return `${isPromise? 'async ' : ''}(${params.join(',')}) => {\t\n\t${getReturnStr()}\n}`;
            }
            return "() => {\t\n\t\n}";
        }else {
            return "";
        }
    });
    const ref = useRef<any>();

    useEffect(() => {
        setValue(value);
    }, [props.value])

    return (
        <div>
            {isHljs? (
                <Hljs code="JavaScript"
                    preProps={{ 
                        onClick: () => {
                            if(!props.disabled){
                                setVisible(true)   
                            }
                        }
                    }}
                >
                    {props.value || ""}
                </Hljs>
            ): (
                <Button shape='round' type='primary' icon={<IconCodeBlock />}
                    disabled={props.disabled}
                    onClick={() => {
                        setVisible(true)
                    }}
                >
                    编辑
                </Button>
            )}
            <Modal visible={visible}
                title="JavaScript"
                focusLock={false}
                style={{ width: 800 }}
                onCancel={() => {
                    setVisible(false)
                }}
                onConfirm={async () => {
                    if (props.onChange) {
                        if (value) {
                            if (isFunction) {
                                try {
                                    const tsNode = tsTojsString(value);
                                    const fun = eval(tsNode.outputText);
                                    // 用于判断是否为函数选项
                                    if (typeof fun === 'function') {
                                        setVisible(false)
                                        props.onChange(value)
                                    } else {
                                        Message.error('请输入正确的函数')
                                    }
                                } catch {
                                    Message.error('请输入正确的函数')
                                }
                            } else {
                                setVisible(false)
                                props.onChange(value)
                            }
                        } else {
                            props.onChange(value)
                            setVisible(false);
                        }
                    } else {
                        setVisible(false);
                    }
                }}
            >
                <MonacoJSEditor
                    {...props}
                    selectionVariable
                    // @ts-ignore
                    ref={ref}
                    value={value}
                    onChange={setValue}
                />
            </Modal>
        </div>
    )
}

export default EditFunction;