import config from "mainConfig";
import { loadScript } from "src/utils/lazyload";

/**
 * 将js文本转为可识别js代码
 */
export const jsStringToJs = (value) => {
    const str = value.replace(/(\$j\{)|\s|\}/g, "");
    return decodeURIComponent(str);
}


/**
 * 将js代码转为js文本
 */
export const jsTojsString = (value) => {
    if(!value || typeof value !== 'string') return value;   // 有可能为空文本
    const str = encodeURIComponent(value);
    return `$j{ ${str} }`;
}




/**
 * 将ts代码转为js文本
 */
export const tsTojsString = (value) => {
    // await loadScript(config.typescriptURL);
    // 使用 TypeScript 进行类型检查和转换
    const transformedCode = ts.transpileModule(value, {
        compilerOptions: {
            target: ts.ScriptTarget.ESNext,
            module: ts.ModuleKind.CommonJS,
            jsx: ts.JsxEmit.React,
        },
    });

    return transformedCode;
}