import { Button, Input, InputNumber, Modal, Select, Switch } from "@arco-design/web-react"
import React, { useEffect, useMemo, useState } from "react";
import { MonacoJSONEditor } from '@/components/MonacoEditor';
import { IconEdit } from "@arco-design/web-react/icon";

interface AnyInputProps {
    value: any;
    onChange: (val: any) => void;
}

const ObjectInput = (props: AnyInputProps) => {
    const [visible, setVisible] = useState(false);

    return (
        <React.Fragment>
            <Input disabled
                style={{ width: '75%' }}
                value={JSON.stringify(props.value)}
                addAfter={
                    <Button type='primary' icon={<IconEdit />} onClick={() => setVisible(true)} />
                }
            />
            <Modal visible={visible}
                focusLock={false}
                onCancel={() => setVisible(false)}
                onOk={() => setVisible(false)}
                style={{ width: 600 }}
                hideCancel
            >
                <MonacoJSONEditor 
                    value={typeof props.value === 'object'? props.value : undefined}
                    onChange={props.onChange}
                />
            </Modal>
        </React.Fragment>
    )
}

export default (props:AnyInputProps) => {
    const [select, setSelect] = useState(() => {
        if('value' in props && props.value !== undefined){
            const type = typeof props.value;
            if(type === 'object' && Array.isArray(props.value)) return 'array';
            return type;
        }
        return 'string';
    });

    useEffect(() => {
        switch(select){
            case 'undefined':
            case 'boolean':
            case 'number':
            case 'string':
            case 'object':
            case 'array':
        }
    },[select])

    const inputRender = useMemo(() => {
        switch(select){
            case 'undefined':
                return <Input key="ud" style={{ width: '75%' }} disabled {...props} />
            case 'boolean':
                return (
                    <div className="items-center" style={{ width: '75%', marginLeft: 20 }}>
                        <Switch checked={Boolean(props.value)} onChange={props.onChange} />
                    </div>
                )
            case 'number':
                return <InputNumber style={{ width: '75%' }} {...props} placeholder="请输入" />
            case 'string':
                return <Input key="in" style={{ width: '75%' }} placeholder="请输入" />
            case 'object':
            case 'array':
                return <ObjectInput {...props} />
        }
    },[select, props.value])

    return (
        <Input.Group compact style={{ display: 'flex' }}>
            <Select
                value={select}
                showSearch 
                style={{ width: 110 }}
                onChange={setSelect}
            >
                <Select.Option value='undefined'>undefined</Select.Option>
                <Select.Option value='string'>string</Select.Option>
                <Select.Option value="boolean">boolean</Select.Option>
                <Select.Option value="number">number</Select.Option>
                <Select.Option value="object">object</Select.Option>
                <Select.Option value="array">array</Select.Option>
            </Select>
            {inputRender}
        </Input.Group>
    )
}