import { Card, Collapse, Input, List, Space, Button, Tooltip, Message, Modal } from "@arco-design/web-react";
import PageStore from "../../store";
import { useObserver } from "mobx-react-lite";
import { useEffect, useMemo, useState } from "react";
import styles from '../index.module.less';
import store from '../store';
import { DragView, moduleStore } from "react-converter-code";
import classNames from "classnames";
import { SchemaFormModal } from "@/components/schema";
import ModuleList, { AddModule } from "@/components/ModuleList";
import customStore from './store';
import menuStore from '../store';


interface CustomProps {
    pageStore: PageStore;
}
const Custom = ({ pageStore }: CustomProps) => {

    return useObserver(() => {
  
        useState(() => {
            if(!menuStore.isReady) {
                menuStore.isReady = true;
                menuStore.getComponents(pageStore)
            }
        })

        const modules = useMemo(() => {
            return store.customs;
        },[store.customs])

        const [visible, setVisible] = useState<boolean>(false);
        const [createVisible, setCreateVisible] = useState<boolean>(false);
    
        return (
            <div className={styles.custom}>
                <div className={styles.customBody}>
                <Collapse key={modules.length}
                    bordered={false}
                    defaultActiveKey={modules.map((o) => o.key)}
                    className={styles.collapse}
                >
                    {modules.map((o) => {
                        return (
                            <Collapse.Item key={o.key} name={o.key} header={o.name}>
                            <List
                                className={styles.list}
                                grid={{ gutter: [8, 16], column: 2 }}
                                dataSource={o.modules}
                                render={(item: any) => {
                                return (
                                    <Tooltip content={item.nickname || item.name}>
                                    <List.Item className={styles.listItem} style={{ padding: 0 }}>
                                    <DragView data={item}
                                        onClick={() => {
                                            pageStore.addList(item);
                                        }}
                                    >
                                        {item.imgUrl && (
                                        <div className={styles.item}>
                                            <img
                                            className={styles.image}
                                            alt="dessert"
                                            src={item.imgUrl || require('@/assets/module/component.png')}
                                            />
                                        </div>
                                        )}
                                        <div className={styles.itemName}>
                                        {item.nickname || item.name}
                                        </div>
                                    </DragView>
                                    </List.Item>
                                    </Tooltip>
                                );
                                }}
                            />
                            </Collapse.Item>
                        )
                    })}
                </Collapse>
                </div>
                <Button.Group style={{ display: "flex" }}>
                    <Button
                        type="primary"
                        style={{ flex: "1 0 100px" }}
                        onClick={() => {
                            setVisible(true)
                        }}
                    >更多</Button>
                    <Button type="primary" style={{ flex: "1 0 100px" }}
                        onClick={() => setCreateVisible(true)}
                    >新增组件</Button>
                </Button.Group>
                <Modal
                    visible={visible}
                    className={styles.publicModel}
                    focusLock={false}
                    title="模块列表"
                    style={{ width: '90vw' }}
                    onCancel={() => {
                        setVisible(false);
                    }}
                    footer={null}
                >
                    <ModuleList
                        onAdd={() => {
                            store.getComponents(pageStore);
                        }}
                        onChange={(list) => {
                            for (const item of list) {
                                const element = moduleStore.elements.get(item.moduleId);
                                if(element){
                                    // 更新时如果当前组件已经在使用，则直接进行更新
                                    moduleStore.updateElement(item.moduleId, {
                                        ...element,
                                        ...item,
                                    })
                                }
                            }
                        }}
                    />
                </Modal>
                <AddModule
                    visible={createVisible}
                    onCancel={() => setCreateVisible(false)}
                    onSuccess={() => {
                        Message.success('创建成功');
                        menuStore.getComponents(pageStore);
                        setCreateVisible(false);
                    }}
                />
            </div>
        )

    })
};

export default Custom