import { Divider, Modal, Select, Tooltip } from "@arco-design/web-react";
import store from './store';
import _ from 'lodash';
import * as arcoicons from '@arco-design/web-react/icon';
import React, { useMemo, useState } from "react";
import styles from './index.module.less';
import { getArcoIconModule } from "@/utils/icon";
import { getUuid } from "@/utils";
const { IconApps } = arcoicons;


const Icon = (props: any) => {

    const [visible, setVisible] = useState<boolean>(false);

    const listRight = useMemo(() => {
        const list = new Array(12).fill(0);
        return  list.map((o, i) => {
            return (
                <div key={i} className={styles['list-item-placeholder']}></div>
            )
        })
    },[])

    const value = useMemo(() => {
        if(props.type == 'string') return props.value;
        if(typeof props.value == 'object' && !Array.isArray(props.value)){
            return props.value.name
        }
        return undefined;
    },[props.value])

    const onChange = (key) => {
        if(props.type == 'string') {
            return props.onChange(key);
        } 
        if(key){
            const option = {
                ..._.pick(getArcoIconModule(key), ['key', 'name', 'nickname']),
                props: {},
                // id: `u${this.getIndex()}`,
                id: getUuid("hash"),
            };
            props.onChange(option);
        }else {
            props.onChange(key)
        }
    }

    return (
        <React.Fragment>
            <Select
                placeholder="选择图标"
                className={styles['select-icon']}
                allowClear
                showSearch
                // renderFormat={(option) => {
                //     const Element = () => "无";
                //     return (
                //         <span>
                //             {Element}
                //             <span style={{ marginLeft: 10 }}>{option.value}</span>
                //         </span>
                //     );
                // }}
                addBefore={<IconApps style={{ cursor: 'pointer' }} onClick={() => setVisible(true)} />}
                {...props}
                value={value}
                onChange={onChange}
            >
                {store.list.map((o, i) => {
                    const Element = arcoicons[o] || (() => null);

                    return (
                        <Select.Option key={i} value={o}>
                            <Element />
                            <span style={{ marginLeft: 10 }}>{o}</span>
                        </Select.Option>
                    )
                })}
            </Select>
            <Modal
                visible={visible}
                style={{ width: 1000 }}
                onCancel={() => setVisible(false)}
                onOk={() => setVisible(false)}
                className="arco-modal-page-html"
                footer={null}
                title="选择图标"
            >
                <div style={{ height: '80vh', overflowY: 'auto' }}>
                {store.categoryList.map((o) => {
                    return (
                        <div key={o.key}>
                            <Divider orientation="center">
                                {o.title}
                            </Divider>
                            <div className={styles['icon-list']}>
                                {o.list.map((key) => {
                                    const Element = arcoicons[key] || (() => null);
                                    return (
                                        <div key={key} className={styles['icon-item']}
                                            onClick={() => {
                                                if(props.onChange){
                                                    onChange(key);
                                                    setVisible(false);
                                                }
                                            }}
                                        >
                                            <div className={styles['icon-view']}>
                                                <Element />
                                                <div style={{ fontSize: 10, marginTop: 10 }}>{key.replace("Icon", '')}</div>
                                            </div>
                                            {/* <div className={styles['icon-name']}>
                                                {key}
                                            </div> */}
                                        </div>
                                    )
                                })}
                                {listRight}
                            </div>
                        </div>
                    )
                })}
                </div>
            </Modal>
        </React.Fragment>
    )
}

export default Icon;