import { ModuleItem } from "@/components/CustomPage/interface";
import _ from 'lodash';
import { moduleStore } from "react-converter-code";
import ajax from "@/utils/ajax";
import app from "@/store/app";
import { getModuleItem } from "@/utils/module";
import { init } from "i18next";
import { Message, Modal } from "@arco-design/web-react";
import { action, observable, toJS, makeObservable } from "mobx";


class ModuleStore {
    nameMap = new Map();
    keyMap = new Map();

    @observable loading: boolean = false;
    @observable list: ModuleItem[] = [];

    contextList = [];

    @action setLoading = (bool: boolean) => {
        this.loading = bool;
    }
    @action setList = (list) => {
        this.list = list;
    }

    getModuleName = (name) => {
        if(!this.nameMap.has(name)) return name;
        let i = 1;
        while(this.nameMap.has(`${name}${i}`)){
            i++;
        }
        return `${name}${i}`;
    }

    setModulesList = (modules: ModuleItem[]) => {
        this.nameMap = new Map(modules.map((o) => [o.name, true]));
        const list: any[] = Array.from(moduleStore.elements.values());
        for (const item of list) {
            this.nameMap.set(item.name, true);
            this.keyMap.set(item.key, item.id);
        }
        this.keyMap = new Map(modules.map((o) => [o.key, o.id]));
        const map = new Map([...modules, ...list].map((o) => [o.key, _.pick(o, ['key', 'name', 'source'])]));
        const result: any[] = Array.from(map.values());
        // console.log('result', result, modules);
        this.contextList = result.filter((o) => o.source === "context");
    }

    /**
     * 这边只是获取模块名称，用于模块名称检测
     */
    init = () => {
        return ajax.post('/apijson/post', {
            'Module[]': {
                count: 0,
                Module: {
                    platform: app.platform,
                    "@column": "id,moduleId,name,imgUrl,nickname",
                    "@order": "createdAt+"
                }
            }
        }).then((res) => {
            this.setModulesList(res.Module.map((o) => ({ ...o, key: o.moduleId})))
        })
    }

    constructor() {
        makeObservable(this);
    }

    // 获取当前租户，模块列表 
    getModuleList(){
        if(this.loading) return;
        this.setLoading(true);
        ajax.post('/apijson/get', {
            'Module[]': {
              count: 0,
              Module: {
                // "moduleId{}": pageStore.moduleFilterIds,
                platform: app.platform,
                // deletedTime: 0,
                "@column": "id,moduleId,updatedAt,name,imgUrl,nickname,description,deletedTime,category,display,extraInfo,platform,price,manufacturer,props,source",
                "@order": "updatedAt-"
              }
            }
        }).then((res) => {
            this.setModulesList(res.Module.map((o) => ({ key: o.moduleId, ...o })));
            const list = res.Module.filter((o) => o.deletedTime == 0).map((o) => {
                return getModuleItem(o);
            })
            this.setList(list);

            return list;
        }).finally(() => {
            this.setLoading(false)
        })
    }




    /**
     * 已经确认要同步
     * @param cList 要新增的组件
     * @param uList 要更新的组件
     */
    syncModuleOk =  async ({ cList, uList }, notMessage: boolean = false) => {

        let params = {};
        if(cList.length){
            // 添加需要新增的组件
            params['post'] = {
            "Module[]": cList.map(({ id, ...o }) => {
                return {
                ...o,
                name: this.getModuleName(o.name),
                }
            })
            }
        }
        if(uList.length){
            // 添加需要更新的组件
            params['put'] = {
            "Module[]": uList.map((o) => {
                return {
                ...o,
                id: this.keyMap.get(o.moduleId)
                }
            })
            }
        }
        console.log('params', params);
        await ajax.post('/apijson/transaction', params).then(() => {
            if(!notMessage){
                Message.success("下载成功");
            }
        });
    }


    /**
     * 同步组件列表
     */
    syncModule = async (list: any[], notMessage: boolean = false) => {
        let components = [];
        list.forEach((o) => {
            components.push(o.moduleId);
            if(o.extraInfo){
            if(o.extraInfo.components){
                components = components.concat(toJS(o.extraInfo.components));
            }
            }
        })
        const keys = Array.from(new Set(components));
        // 获取所有组件列表
        const lists = await ajax.post('/apijson/get', {
            "PublicModule[]":{
            "count":0,
            "PublicModule":{
                "@column":"id,appId,moduleId,pluginId,name,nickname,imgUrl,description,category,display,platform,price,manufacturer,props,source,content,jsxRender,extraInfo",
                "moduleId{}": keys,
                "@order":"updatedAt-"
            },
            }
        }).then((res) => res.PublicModule.map((o) => {
            return {
            ...o,
            props: JSON.parse(o.props || '{}'),
            extraInfo: JSON.parse(o.extraInfo || '{}'),
            }
        }));
    
        // 检测需要新增的组件
        let createList = lists.filter((o) => !this.keyMap.has(o.moduleId));
        // 检测需要更新的组件
        let updateList = lists.filter((o) => this.keyMap.has(o.moduleId));

        console.log('lists', lists, createList, updateList)
        let content = "";
        if(!notMessage){
            // 需要提示
            if(createList.length && updateList.length){
                content = `当前共需要下载（${
                createList.map((o) => o.nickname || o.name).join('、')
                }）组件，同时以下（${
                updateList.map((o) => o.nickname || o.name).join('、')
                }）组件已经存在将会被一起更新，请注意当前更新影响组件较多，同步后将会影响本地组件已修改的内容`
            }else if(createList.length){
                content = `请确认下载（${
                createList.map((o) => o.nickname || o.name).join('、')
                }）组件`
            }else if(updateList.length){
                content = `当前无新增组件，以下（${
                updateList.map((o) => o.nickname || o.name).join('、')
                }）组件需要进行更新，请注意更新会将本地已修改组件内容覆盖，`
            }
            Modal.confirm({
                title: "下载提示",
                content,
                onOk: () => {
                    return this.syncModuleOk({
                        cList: createList,
                        uList: updateList
                    }, notMessage);
                }
            })
        }else {
            // 不需要提示
            await this.syncModuleOk({
                cList: createList,
                uList: updateList
            }, notMessage);
        }

    }
}

export default new ModuleStore();